/**
 * @module O 内容工具箱
 *
 * combat.skill 投影器——把 Resource Graph 中的 combat.skill 节点投影回
 * oblivions/gamedata/combat_skill_config.php 的 PHP 数组形态。
 *
 * 设计意图（执行案 06-P5 §4.3.2）：
 * - P5-2 改用 generatePhpFile API：文件头注入 `// AUTO-GENERATED FROM ...` 注释、
 *   模块标签与 sectionTitle 由 schema.projectionTargets 派生，不再使用硬编码文件头。
 * - combat.skill 节点 id 是 act_id（如 'move' / 'unarmed_strike'），data 是该技能的
 *   战斗配置数组（pipeline / aim / capture / execution / delivery / ap_calc / range /
 *   rules / effects / finisher 等嵌套字段）。
 * - 字段顺序按节点 data 的 key 插入顺序保留——TS 对象保留 string key 顺序，
 *   loader 从 combat_skill_config.php 解析时按文件顺序写入，投影时按图顺序输出。
 * - 多层嵌套（aim / capture / execution / delivery / range / rules）由 renderPhpValue
 *   递归输出，无需特殊处理。
 *
 * 字段映射：
 *   - 节点 id              → 顶层 key（act_id，如 'move'）
 *   - node.data.{field}    → entry 字段（pipeline / aim / capture / execution / ...）
 *
 * 边界：
 * - 节点 data 为 null/非对象时跳过该节点
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 * - 节点 id 必须匹配 /^[a-z][a-z0-9_]*$/，否则跳过（idPattern 校验）
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='combat.skill' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const COMBAT_SKILL_CONFIG_FILE_PATH = 'oblivions/gamedata/combat_skill_config.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const COMBAT_SKILL_CONFIG_AUTHOR_SOURCE = 'oblivions/content/skills/combat-skill-config.yaml';

/** combat.skill 节点 id 正则——与 schema idPattern 对齐 */
const COMBAT_SKILL_ID_PATTERN = /^[a-z][a-z0-9_]*$/;

/**
 * 把 combat.skill 节点投影回 combat_skill_config.php 形态。
 *
 * @param nodes combat.skill 节点数组（顺序保留为顶层 act_id 顺序）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/combat_skill_config.php）
 */
export function projectCombatSkillConfig(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildCombatSkillDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'H 战斗与技能系统',
    sectionTitle: 'Oblivions 战斗技能配置表',
    autoGeneratedFrom: COMBAT_SKILL_CONFIG_AUTHOR_SOURCE,
  });
  return [{ filePath: COMBAT_SKILL_CONFIG_FILE_PATH, content }];
}

/**
 * 把 combat.skill 节点重建为 combat_skill_config.php 字典形态。
 *
 * 节点 id 作为顶层 key（act_id），node.data 作为 value（含 pipeline / aim / capture /
 * execution / delivery / ap_calc / range / rules / effects / finisher 等字段）。
 * stripUndefinedFields 递归移除 undefined 字段。
 *
 * 多层嵌套（aim / capture / range / rules）由 renderPhpValue 递归处理，无需特殊代码。
 */
function buildCombatSkillDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (!COMBAT_SKILL_ID_PATTERN.test(node.id)) continue;
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const cleaned = stripUndefinedFields(node.data);
    dict[node.id] = cleaned as PhpValue;
  }
  return dict;
}

/**
 * 递归移除 undefined 字段——与 php-adapter.stripUndefinedFields 行为一致。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
